double dist2(CloudPt *a, CloudPt *b)
{
  double dx;
  double dy;
  dx = a->x - b->x;
  dy = a->y - b->y;
  return dx * dx + dy * dy;
}

int closest_ix(CloudPt *pts, int n, CloudPt *query)
{
  int best;
  int i;
  double best_d;
  double d;
  best = 0;
  best_d = dist2(pts, query);
  i = 1;
  while (i < n) {
    d = dist2(pts + i, query);
    if (d < best_d) {
      best_d = d;
      best = i;
    }
    i = i + 1;
  }
  return best;
}

double span_len(CloudPt *pts, int n)
{
  double total;
  int i;
  total = 0.0;
  i = 1;
  while (i < n) {
    total = total + dist2(pts + (i + -1), pts + i);
    i = i + 1;
  }
  return total;
}

int main(void)
{
  CloudPt cloud[2];
  CloudPt query;
  int idx;
  cloud[0].x = 0.0;
  cloud[0].y = 0.0;
  cloud[1].x = 3.0;
  cloud[1].y = 4.0;
  query.x = 1.0;
  query.y = 1.0;
  printf("heldout\n");
  idx = closest_ix(cloud, 2, &query);
  (void)span_len(cloud, 2);
  return idx;
}
